//! [`DerivedMedia`]: copies of an asset generated by the media pipeline (ADR-0007).

use serde::{Deserialize, Serialize};
use ts_rs::TS;

/// The mezzanine and proxy of an asset. The original is [`super::Asset::original_path`].
#[derive(Debug, Clone, PartialEq, Eq, Default, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
pub struct DerivedMedia {
    /// High-quality decodable copy, for originals WebCodecs cannot decode.
    pub mezzanine: Option<DerivedFile>,
    /// Low-resolution copy for smooth playback.
    pub proxy: Option<DerivedFile>,
}

/// One generated file and the outcome of its job.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
pub struct DerivedFile {
    /// Location relative to the project folder, `/`-separated.
    pub relative_path: String,
    /// Whether the file can be used. Job progress is runtime state, not stored here.
    pub status: DerivedStatus,
}

/// Outcome of the job producing a derived file.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(tag = "kind", rename_all = "camelCase")]
pub enum DerivedStatus {
    /// Queued or running.
    Pending,
    /// Written and usable.
    Ready,
    /// The job failed; the original (or nothing) is used instead.
    Failed {
        /// Why, for the user and for agents.
        message: String,
    },
}
